; Lost jet animation
; $5690-$56f3

; Lost jet in the air: sprite 7 follows the jet with frames $90-$93. On the ground (Y >= $7f, climb 0): wreck frames $88-$8f, then up to $90.
jet_lost_animate
        lda SP0Y
        cmp #$7f
        bcc jet_lost_air_sprite7
        lda jet_climb                   ; Ground test: Y >= $7f and jet_climb = 0.
        bne jet_lost_air_sprite7
        lda crash_stage
        cmp #$90
        beq jet_lost_ground_frames
        lda RANDOM                      ; SID voice 3 output as a random number.
        and #$07
        clc
        adc #$88
        sta SPRPTR
        lda SPENA                       ; Sprite 7 off.
        and #$7f
        sta SPENA
        lda SPMC                        ; Jet sprite multicolour, colour 1.
        ora #$01
        sta SPMC
        lda #$01
        sta SP0COL
        bne jet_lost_animate_done
jet_lost_ground_frames
        lda tick                        ; $24 = $90: every 8th tick the frame + 1 up to $90.
        and #$07
        bne jet_lost_animate_done
        lda SPRPTR
        cmp #$90
        bcs jet_lost_animate_done
        inc SPRPTR
        bne jet_lost_animate_done
jet_lost_air_sprite7
        lda SPENA
        ora #$80
        sta SPENA
        jsr sprite7_follow_jet
        lda smoke_sprite_ptr
        bne jet_lost_sprite7_check
jet_lost_sprite7_first
        lda #smoke_sprites / 64
        sta smoke_sprite_ptr
        bne jet_lost_animate_done
jet_lost_sprite7_check
        cmp #$93
        bcs jet_lost_sprite7_first
        inc smoke_sprite_ptr
jet_lost_animate_done
        rts
